//! `beacon gen`: typed emitters for Python and TypeScript from a source's declarations, as
//! `spec/clients.md` describes.
//!
//! Each generated file is self-contained: the client (`clients/python/beacon_client.py` or
//! `clients/node/beacon_client.ts`, the part between its `runtime` markers) followed by one function
//! per declared kind. Application code calls only those functions, so an undeclared kind, a missing
//! or extra fact or slot, or a fact of the wrong type fails its own type check.
//!
//! The same declarations always give the same text, so `beacon gen --check` finds a stale file by
//! generating again and comparing. The header also carries a hash of the declarations' JSON form, so
//! a person (or a script) can see at a glance which declarations a file was made from.

use beacon_core::Problem;
use beacon_core::decl::{Declarations, Kind};
use std::collections::BTreeMap;

mod python;
mod typescript;

#[cfg(test)]
mod tests;

/// The generator's version, written into every file's header.
pub const VERSION: &str = env!("CARGO_PKG_VERSION");

const PYTHON_CLIENT: &str = include_str!("../../../clients/python/beacon_client.py");
const TYPESCRIPT_CLIENT: &str = include_str!("../../../clients/node/beacon_client.ts");

/// A language `beacon gen` writes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Language {
    Python,
    TypeScript,
}

impl Language {
    pub const ALL: [Language; 2] = [Language::Python, Language::TypeScript];

    pub fn name(self) -> &'static str {
        match self {
            Language::Python => "python",
            Language::TypeScript => "typescript",
        }
    }

    pub fn parse(text: &str) -> Option<Language> {
        match text {
            "python" | "py" => Some(Language::Python),
            "typescript" | "ts" => Some(Language::TypeScript),
            _ => None,
        }
    }

    /// The file extension a generated file should have.
    pub fn extension(self) -> &'static str {
        match self {
            Language::Python => "py",
            Language::TypeScript => "ts",
        }
    }
}

/// The generated file for `decl` in `language`. Run [`check`] first: declarations with a problem
/// there give a file that doesn't compile.
pub fn generate(decl: &Declarations, language: Language) -> String {
    match language {
        Language::Python => python::generate(decl),
        Language::TypeScript => typescript::generate(decl),
    }
}

/// A hash of the declarations' JSON form (FNV-1a, 64 bits, as 16 hex digits). It changes whenever
/// anything published would change, and not when only the TOML's comments or layout do.
pub fn hash(decl: &Declarations) -> String {
    let text = decl.to_json().to_string();
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for byte in text.bytes() {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(0x0100_0000_01b3);
    }
    format!("{hash:016x}")
}

/// The words of the header, the same in both languages.
fn header_lines(decl: &Declarations) -> [String; 3] {
    [
        format!(
            "Generated by `beacon gen` {VERSION} from the declarations of `{}`. Do not edit.",
            decl.source
        ),
        "Change kinds.toml and run `beacon gen` again; `beacon gen --check` fails while this file is stale."
            .to_string(),
        format!("declarations: fnv1a64 {}", hash(decl)),
    ]
}

/// Reads the hash out of a generated file's header, to compare with [`hash`] without generating.
pub fn hash_in(text: &str) -> Option<&str> {
    text.lines()
        .take(5)
        .find_map(|line| line.split_once("declarations: fnv1a64 "))
        .map(|(_, hash)| hash.trim())
}

/// The part of a client file between its `runtime start` and `runtime end` markers.
fn runtime(client: &str) -> &str {
    let start = client
        .find("--- runtime start ---")
        .and_then(|at| client[at..].find('\n').map(|end| at + end + 1));
    let end = client.find("--- runtime end ---").and_then(|at| {
        // Back to the start of the marker's line.
        client[..at].rfind('\n').map(|line| line + 1)
    });
    match (start, end) {
        (Some(start), Some(end)) if start <= end => &client[start..end],
        _ => "",
    }
}

/// The kinds that have a lifecycle (alerts and actions): the ones a snapshot covers, and the ones
/// that get `_resolved` and `_entry` functions.
fn lifecycle_kinds(decl: &Declarations) -> Vec<&str> {
    decl.kinds
        .iter()
        .filter(|(_, kind)| kind.class.has_lifecycle())
        .map(|(name, _)| name.as_str())
        .collect()
}

/// The function names one kind becomes in a language: the kind's own, and for an alert or action
/// its `resolved` and `entry` companions.
fn function_names(name: &str, kind: &Kind, language: Language) -> Vec<String> {
    let base = match language {
        Language::Python => python::function(name),
        Language::TypeScript => typescript::function(name),
    };
    let mut names = vec![base.clone()];
    if kind.class.has_lifecycle() {
        match language {
            Language::Python => {
                names.push(format!("{base}_resolved"));
                names.push(format!("{base}_entry"));
            }
            Language::TypeScript => {
                names.push(format!("{base}Resolved"));
                names.push(format!("{base}Entry"));
            }
        }
    }
    names
}

/// Problems only generating shows: two kinds that would give the same function name, and fact or
/// slot names that can't be a Python argument. `beacon check`, `gen` and `publish` all run it.
pub fn check(decl: &Declarations) -> Vec<Problem> {
    let mut problems = Vec::new();
    for language in Language::ALL {
        let mut seen: BTreeMap<String, &str> = BTreeMap::new();
        for (name, kind) in &decl.kinds {
            for function in function_names(name, kind, language) {
                match seen.get(&function) {
                    Some(first) if *first != name.as_str() => problems.push(Problem::new(
                        format!("kinds.toml: kinds.\"{name}\""),
                        format!(
                            "`{first}` and `{name}` both give the {} function `{function}`, so one would hide the other",
                            match language {
                                Language::Python => "Python",
                                Language::TypeScript => "TypeScript",
                            }
                        ),
                        "rename one of them so the names differ in more than `.`, `_` and `-`, and neither ends in `_resolved` or `_entry`",
                    )),
                    Some(_) => {}
                    None => {
                        seen.insert(function, name);
                    }
                }
            }
        }
    }
    for (name, kind) in &decl.kinds {
        for (field, value) in kind
            .facts
            .keys()
            .map(|f| ("facts", f))
            .chain(kind.slots.keys().map(|s| ("slots", s)))
        {
            if python::KEYWORDS.contains(&value.as_str()) {
                problems.push(Problem::new(
                    format!("kinds.toml: kinds.\"{name}\".{field}.{value}"),
                    format!(
                        "`{value}` is a Python keyword, so it can't be an argument of the generated function"
                    ),
                    format!("rename it, like `{value}_name` or a word that says more"),
                ));
            }
        }
    }
    problems
}

/// Escapes text for a double-quoted string literal (Python and TypeScript agree on these).
fn quote(text: &str) -> String {
    let mut out = String::with_capacity(text.len() + 2);
    out.push('"');
    for c in text.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", u32::from(c))),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}
